def transform(grid):
    # Locate the repeated 3-row color key, mapping each color in the strip to itself.
    # The key is situated below a monochrome pattern; replace that pattern by the key's sequence colors.
    h, w = len(grid), len(grid[0])
    rows = [r for r in range(h) if any(grid[r])]
    # Identify contiguous nonzero row groups.
    groups=[]
    for r in rows:
        if not groups or r > groups[-1][-1]+1: groups.append([r])
        else: groups[-1].append(r)
    # Upper pattern group contains the object; lower group is the color code.
    obj=groups[0]
    key=groups[-1]
    colors=[]
    for c in range(w):
        vals={grid[r][c] for r in key if grid[r][c]}
        if vals: colors.append((c,next(iter(vals))))
    # In demo, matching motif is separated into stacked colored-coded rows; recolor earlier shape rowwise
    # Each color-code row corresponds to a horizontal layer of the following repeated shape.
    out=[row[:] for row in grid]
    if len(key)>=3 and len(obj)>=3:
        # key bands provide row colors; apply to object rows in order, maintaining shape.
        palette=[]
        for r in key:
            vals=[x for x in grid[r] if x]
            if vals: palette.append(vals[0])
        # Pattern is transformed by shifting it vertically down to align with key, while recoloring original
        # observed demo: upper silhouette is recolored using palette [4,1,6], then moved? Actually output shape at upper location is 4s,
        # center motif remains 1, lower remains 6: key 4,1,6 mapped to the three repeated object layers.
        # Process repeated silhouette rows by color codes assigned from key, target silhouette layer in test is entire object.
        # Use shape rows and infer color by key columns: key has vertical sequence corresponding to silhouette's row structure.
        for i,r in enumerate(obj):
            # retain colors unless shape has 1s; map based on vertical layer where the key row's color applies
            if i < len(palette):
                for c in range(w):
                    if grid[r][c]==1: out[r][c]=palette[i]
        # Demo transformation actually key (4,1,6 columns) becomes color layers of the silhouette shifted downward by 5 rows;
        # remove key and shift the 1-silhouette? output kept object at rows 7-11 and lower colored object rows 12-16.
        # Thus duplicate shape using key colors, replacing key itself.
        for r in key:
            out[r]=[0]*w
        # generate copy of object translated so top aligns at key start, with color based on key color at each object row rank
        for i,r in enumerate(obj):
            nr=key[0]+i
            if nr<h:
                col=palette[min(i, len(palette)-1)]
                for c in range(w):
                    if grid[r][c]: out[nr][c]=col
    return out
