def transform(grid):
    h, w = len(grid), len(grid[0])
    unseen={(r,c) for r in range(h) for c in range(w) if grid[r][c]}
    comps=[]
    while unseen:
        stack=[unseen.pop()]; comp=set(stack)
        while stack:
            r,c=stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen:
                    unseen.remove(p); comp.add(p); stack.append(p)
        comps.append(comp)
    motif=min(comps,key=len)
    r0=min(r for r,c in motif); c0=min(c for r,c in motif)
    pattern={(r-r0,c-c0) for r,c in motif}
    mh=max(r for r,c in pattern)+1
    key=max((co for co in comps if co is not motif),key=len)
    colors=[]
    for c in range(w):
        vals=[grid[r][c] for r in range(h) if (r,c) in key]
        if vals: colors.append(vals[0])
    out=[[0]*w for _ in range(h)]
    # Stack copies of the motif, centered vertically around its original location.
    start=r0-(len(colors)//2)*mh
    for i,color in enumerate(colors):
        top=start+i*mh
        for dr,dc in pattern:
            r,c=top+dr,c0+dc
            if 0<=r<h and 0<=c<w: out[r][c]=color
    return out
